#!/usr/bin/env node
// Preference store: a saved preference survives process restart (CS-1).
// Usage: node src/pref.js set <value> | get | restore <value>
// Storage is scoped to PREF_FILE (default: .pref.json in the current project) so
// callers can isolate it to a scratch project and never touch other accounts.
'use strict';

const fs = require('fs');
const path = require('path');

const prefFile = path.resolve(process.env.PREF_FILE || path.join(process.cwd(), '.pref.json'));

function read() {
  try {
    return JSON.parse(fs.readFileSync(prefFile, 'utf8')).value;
  } catch (err) {
    if (err.code === 'ENOENT') return undefined;
    throw err;
  }
}

function write(value) {
  fs.mkdirSync(path.dirname(prefFile), { recursive: true });
  // Write to a temp file then rename, so a crash mid-write never leaves a torn file.
  const tmp = `${prefFile}.${process.pid}.tmp`;
  fs.writeFileSync(tmp, JSON.stringify({ value }), 'utf8');
  fs.renameSync(tmp, prefFile);
}

function main([cmd, value]) {
  switch (cmd) {
    case 'get': {
      const current = read();
      if (current === undefined) return 1;
      process.stdout.write(`${current}\n`);
      return 0;
    }
    case 'set':
    case 'restore':
      if (value === undefined) {
        process.stderr.write(`usage: pref.js ${cmd} <value>\n`);
        return 2;
      }
      write(value);
      return 0;
    default:
      process.stderr.write('usage: pref.js set <value> | get | restore <value>\n');
      return 2;
  }
}

process.exitCode = main(process.argv.slice(2));

